EAC 内核组件主要在 `EasyAntiCheat.sys`（服务名 `EasyAntiCheat`），主要检测点：

| 检测点 | 机制 | 验证方法 |
|---|---|---|
| 驱动签名/证书链 | `CiValidateImageHeader` + 自身白名单 | 加载未签名驱动看 `STATUS_INVALID_IMAGE_HASH` |
| 未签名驱动枚举 | `PsLoadedModuleList` 遍历 + `\Driver` 对象扫描 | WinDbg `!drvobj` 或自己枚举对比 |
| 句柄权限 | `ObRegisterCallbacks` 剥 `PROCESS_VM_READ/WRITE` | 打开目标进程看返回的 `GrantedAccess` |
| CR3/EPROCESS 篡改 | 定期快照 `EPROCESS.DirectoryTableBase` 比对 | 对比驱动前后 `PsGetProcessId` 链 |
| SSDT/inline hook | `KiServiceTable` 校验、`.text` hash | 扫描 ntoskrnl `.text` 段 hash |
| DMA/IOMMU | VT-d 检测（部分配置） | 硬件层，软件不处理 |
| 内存扫描 | 对可疑驱动内存做 AOB 扫描 | 检查驱动 `.data` 段是否有可疑特征 |

**第二步：驱动骨架（WDM，最小读写）**

```c
// eac_rw.c - WDM 最小驱动，MmCopyVirtualMemory 读写
#include <ntifs.h>

#define DEVICE_NAME L"\\Device\\EacRw"
#define SYMLINK_NAME L"\\DosDevices\\EacRw"

typedef struct _RW_REQUEST {
    HANDLE ProcessId;
    PVOID  Address;
    PVOID  Buffer;
    SIZE_T Size;
    BOOLEAN Write;
} RW_REQUEST, *PRW_REQUEST;

static NTSTATUS DispatchCreate(PDEVICE_OBJECT DevObj, PIRP Irp) {
    Irp->IoStatus.Status = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static NTSTATUS DispatchClose(PDEVICE_OBJECT DevObj, PIRP Irp) {
    Irp->IoStatus.Status = STATUS_SUCCESS;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static NTSTATUS DispatchIoctl(PDEVICE_OBJECT DevObj, PIRP Irp) {
    PIO_STACK_LOCATION stack = IoGetCurrentIrpStackLocation(Irp);
    NTSTATUS status = STATUS_INVALID_DEVICE_REQUEST;
    ULONG info = 0;

    if (stack->Parameters.DeviceIoControl.IoControlCode == 0x00222000 &&
        stack->Parameters.DeviceIoControl.InputBufferLength >= sizeof(RW_REQUEST)) {
        PRW_REQUEST req = (PRW_REQUEST)Irp->AssociatedIrp.SystemBuffer;
        PEPROCESS target = NULL;
        status = PsLookupProcessByProcessId(req->ProcessId, &target);
        if (NT_SUCCESS(status)) {
            SIZE_T copied = 0;
            KAPC_STATE apc;
            KeStackAttachProcess(target, &apc);
            status = MmCopyVirtualMemory(PsGetCurrentProcess(), req->Buffer,
                                         target, req->Address, req->Size,
                                         KernelMode, &copied);
            KeUnstackDetachProcess(&apc);
            ObDereferenceObject(target);
            info = (ULONG)copied;
        }
    }
    Irp->IoStatus.Status = status;
    Irp->IoStatus.Information = info;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

static NTSTATUS DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath) {
    UNICODE_STRING devName, symName;
    PDEVICE_OBJECT devObj = NULL;
    NTSTATUS status;

    RtlInitUnicodeString(&devName, DEVICE_NAME);
    status = IoCreateDevice(DriverObject, 0, &devName, FILE_DEVICE_UNKNOWN,
                            FILE_DEVICE_SECURE_OPEN, FALSE, &devObj);
    if (!NT_SUCCESS(status)) return status;

    RtlInitUnicodeString(&symName, SYMLINK_NAME);
    status = IoCreateSymbolicLink(&symName, &devName);
    if (!NT_SUCCESS(status)) { IoDeleteDevice(devObj); return status; }

    DriverObject->MajorFunction[IRP_MJ_CREATE] = DispatchCreate;
    DriverObject->MajorFunction[IRP_MJ_CLOSE] = DispatchClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = DispatchIoctl;

    return STATUS_SUCCESS;
}
```

