    PVOID SectionPointer;
    ULONG CheckSum;
    ULONG TimeDateStamp;
} KLDR_DATA_TABLE_ENTRY, *PKLDR_DATA_TABLE_ENTRY;

NTSTATUS UnlinkSelfFromModuleList(VOID)
{
    PKLDR_DATA_TABLE_ENTRY self =
        (PKLDR_DATA_TABLE_ENTRY)DriverObject;
    // DriverObject 不是 LDR 项，用下面正确入口（见 DriverEntry 内实现）
