```cpp
// x64，MSVC /W4 /std:c++20，目标 [进程名]（如 Game.exe）
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>
#include <vector>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof pe };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe))
        do { if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; } }
        while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

static uintptr_t ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    MODULEENTRY32W me{ sizeof me };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me))
        do { if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; } }
        while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

// 读操作：先用 NtReadVirtualMemory，RPM 作为回退
typedef NTSTATUS(NTAPI* pNtReadVirtualMemory)(HANDLE, PVOID, PVOID, SIZE_T, PSIZE_T);

class Mem {
public:
    HANDLE h = nullptr;
    pNtReadVirtualMemory NtRpm = nullptr;

    bool Open(const wchar_t* proc, const wchar_t* mod, uintptr_t& outBase, DWORD& outPid) {
        outPid = FindPid(proc);
        if (!outPid) return false;
        h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, outPid);
        if (!h) return false;
        outBase = ModuleBase(outPid, mod);
        HMODULE ntdll = GetModuleHandleW(L"ntdll.dll");
        if (ntdll) NtRpm = (pNtReadVirtualMemory)GetProcAddress(ntdll, "NtReadVirtualMemory");
        return outBase != 0;
    }

    template <class T> bool R(uintptr_t addr, T& v) {
        SIZE_T got = 0;
        if (NtRpm) return NtRpm(h, (PVOID)addr, &v, sizeof(T), &got) >= 0 && got == sizeof(T);
        return ReadProcessMemory(h, (LPCVOID)addr, &v, sizeof(T), &got) && got == sizeof(T);
    }
    bool R(uintptr_t addr, void* buf, size_t n) {
        SIZE_T got = 0;
        if (NtRpm) return NtRpm(h, (PVOID)addr, buf, n, &got) >= 0 && got == n;
        return ReadProcessMemory(h, (LPCVOID)addr, buf, n, &got) && got == n;
    }
};
```

