## 2. 读写封装

```cpp
HANDLE g_hProc = nullptr;
bool Attach(DWORD pid) {
    g_hProc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    return g_hProc != nullptr;
}

template <typename T> T R(uintptr_t addr) {
    T v{}; if (!addr) return v;
    SIZE_T n = 0; ReadProcessMemory(g_hProc, (LPCVOID)addr, &v, sizeof(T), &n);
    return v;
}
template <typename T> bool W(uintptr_t addr, T v) {
    SIZE_T n = 0; return WriteProcessMemory(g_hProc, (LPVOID)addr, &v, sizeof(T), &n);
}

// 多级指针链：offsets 从外层到内层
uintptr_t ResolveChain(uintptr_t base, std::vector<uintptr_t> offsets) {
    uintptr_t addr = base;
    for (size_t i = 0; i < offsets.size(); ++i) {
        addr = R<uintptr_t>(addr);
        if (!addr) return 0;
        addr += offsets[i];
    }
    return addr;
}
```

