constexpr uintptr_t OFF_LEVEL   = 0x[偏移];   // UWorld->PersistentLevel
constexpr uintptr_t OFF_ACTORS  = 0x[偏移];   // ULevel->Actors (TArray)
constexpr uintptr_t OFF_ACTORCOUNT = 0x[偏移];

struct FNameEntry { int32_t Index; char Name[64]; };

std::vector<uintptr_t> GetActors() {
    std::vector<uintptr_t> out;
    uintptr_t world = R<uintptr_t>(g_base + OFF_GWORLD + /*GWorld 本身是指针*/0);
    uintptr_t level = R<uintptr_t>(world + OFF_LEVEL);
    uintptr_t arr   = R<uintptr_t>(level + OFF_ACTORS);      // Data
    int32_t  cnt    = R<int32_t>(level + OFF_ACTORCOUNT);    // Num
    if (!arr || cnt <= 0 || cnt > 65536) return out;
    for (int i = 0; i < cnt; ++i) {
