#include <ntifs.h>

typedef struct _COPY_REQUEST {
    HANDLE  pid;
    PVOID   src;
    PVOID   dst;
    SIZE_T  size;
    BOOLEAN write;
    NTSTATUS status;
} COPY_REQUEST, *PCOPY_REQUEST;

NTSTATUS DoCopy(PCOPY_REQUEST req) {
    PEPROCESS srcProc = NULL, dstProc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId(req->pid, &srcProc);
    if (!NT_SUCCESS(st)) return st;
    dstProc = PsGetCurrentProcess();

    KAPC_STATE apc;
    KeStackAttachProcess(srcProc, &apc);

    if (req->write) {
        st = MmCopyVirtualMemory(dstProc, req->src, srcProc, req->dst,
                                 req->size, KernelMode, &req->size);
    } else {
        st = MmCopyVirtualMemory(srcProc, req->src, dstProc, req->dst,
                                 req->size, KernelMode, &req->size);
    }

    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(srcProc);
    return st;
}
```

`MmCopyVirtualMemory` 不经过句柄表，`ObRegisterCallbacks` 拦不到。但注意：**它会碰目标的用户态页表，`BEDaisy` 的 CR3 扫描能读到访问痕迹**。所以这是第一版验证通路，不是最终版。

