## 步骤 1：拿模块基址

```cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

DWORD GetPid(const wchar_t* name) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(h, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(h, &pe));
    CloseHandle(h);
    return pid;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(h, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; }
    } while (Module32NextW(h, &me));
    CloseHandle(h);
    return base;
}
```

## 步骤 2：GObjects 特征码（UE4.2x–4.27 通用）

`GObjects` 在 `.data` 里，是一个 `FUObjectArray`，布局关键点：

```
struct FUObjectItem { UObject* Object; int32 Flags; int32 ClusterRootIndex; int32 SerialNumber; };  // 0x10 对齐
struct TUObjectArray { FUObjectItem* Objects; int32 MaxElements; int32 NumElements; };              // 0x0 / 0x8 / 0xC
struct FUObjectArray { int32 ObjFirstGCIndex; int32 ObjLastNonGCIndex; int32 MaxObjectsNotConsideredByGC;
                       bool bOpenForDisregardForGC; TUObjectArray ObjObjects; };                     // 0x10 起是 ObjObjects
```

扫描思路是找「`NumElements` 合理、`Objects` 指针指向堆、`MaxElements >= NumElements`」的候选结构，再拿 `Objects[0]->vtable` 落在主模块 `.text` 范围来验证（固定校验点，不是猜出来的）：

```cpp
struct Reader {
    HANDLE h;
    bool rd(uintptr_t a, void* out, size_t n) {
        SIZE_T got;
        return ReadProcessMemory(h, (LPCVOID)a, out, n, &got) && got == n;
    }
    template<class T> bool get(uintptr_t a, T& v) { return rd(a, &v, sizeof(T)); }
};

// 在 moduleBase+size 范围内扫 GObjects 候选
struct UObjectArray {
    uintptr_t Objects;   // FUObjectItem*
    int32_t   MaxElements;
    int32_t   NumElements;
};

uintptr_t ScanGObjects(Reader& r, uintptr_t modBase, size_t modSize) {
    std::vector<uint8_t> buf(modSize);
    if (!r.rd(modBase, buf.data(), modSize)) return 0;

    std::vector<uintptr_t> cands;
    for (size_t off = 0; off + sizeof(UObjectArray) <= modSize; off += 8) {
        UObjectArray ua;
        memcpy(&ua, buf.data() + off, sizeof(ua));
        if (ua.NumElements <= 0 || ua.NumElements > 0x400000) continue;
        if (ua.MaxElements < ua.NumElements) continue;
        if (ua.MaxElements > 0x800000) continue;
        if (ua.Objects < 0x10000) continue;
        cands.push_back(modBase + off);
    }

    // 验证：item[0].Object 的 vtable 必须在模块 .text 内
    for (uintptr_t g : cands) {
        UObjectArray ua;
        if (!r.get(g, ua)) continue;
        uintptr_t obj0 = 0, vtbl = 0;
        if (!r.get(ua.Objects, obj0) || !obj0) continue;
        if (!r.get(obj0, vtbl)) continue;
        if (vtbl >= modBase && vtbl < modBase + modSize) {
            printf("[+] GObjects = 0x%llX  (Num=%d Max=%d pit=0x%llX)\n",
                (unsigned long long)g, ua.NumElements, ua.MaxElements,
                (unsigned long long)ua.Objects);
            return g;
        }
    }
    return 0;
}
```

