// base_probe.cpp — cl /std:c++17 /EHsc base_probe.cpp
// 用法: base_probe.exe <进程名.exe> <模块名.dll|exe>
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>
#include <string>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

int wmain(int argc, wchar_t** argv) {
    if (argc < 2) { wprintf(L"用法: %s <进程名.exe> [模块名]\n", argv[0]); return 1; }
    const wchar_t* modName = (argc >= 3) ? argv[2] : nullptr;

    DWORD pid = FindPid(argv[1]);
    if (!pid) { wprintf(L"[-] 未找到进程 %s\n", argv[1]); return 2; }

    HANDLE hProc = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!hProc) { wprintf(L"[-] OpenProcess 失败 GetLastError=%lu\n", GetLastError()); return 3; }

    printf("[+] pid = %lu (0x%lX)\n", pid, pid);

    HMODULE mods[1024]; DWORD needed = 0;
    if (!EnumProcessModulesEx(hProc, mods, sizeof(mods), &needed, LIST_MODULES_ALL)) {
        wprintf(L"[-] EnumProcessModulesEx 失败 %lu\n", GetLastError());
        CloseHandle(hProc); return 4;
    }
    DWORD count = needed / sizeof(HMODULE);
    printf("[+] 模块数 %lu\n", count);

    for (DWORD i = 0; i < count; ++i) {
        MODULEINFO mi{}; wchar_t base[MAX_PATH]{};
        if (GetModuleBaseNameW(hProc, mods[i], base, MAX_PATH) &&
            GetModuleInformation(hProc, mods[i], &mi, sizeof(mi))) {
            if (!modName || _wcsicmp(base, modName) == 0)
                wprintf(L"  %-32s base=0x%p size=0x%lX\n", base, mi.lpBaseOfDll, mi.SizeOfImage);
        }
    }
    CloseHandle(hProc);
    return 0;
}
