**多级指针链解析**（`[基址]+0x0` → `+0x10` → `+0x28` 这种链）：

```c
uintptr_t ResolveChain(HANDLE h, uintptr_t base, const uintptr_t* offs, int n) {
    uintptr_t addr = base;
    for (int i = 0; i < n; i++) {
        ReadProcessMemory(h, (LPCVOID)addr, &addr, sizeof(addr), NULL);
        addr += offs[i];
    }
    return addr;
}
// 用法: uintptr_t offs[] = { 0x0, 0x10, 0x28 };  // 全部为占位符
```

**内存区块扫描找特征码（AOB）**，用于定位实体列表 / 函数入口：

```c
uintptr_t AobScan(HANDLE h, uintptr_t start, SIZE_T size, const BYTE* pat, const char* mask) {
    BYTE* buf = malloc(size);
    SIZE_T read = 0;
    ReadProcessMemory(h, (LPCVOID)start, buf, size, &read);
    size_t plen = strlen(mask);
    for (SIZE_T i = 0; i + plen <= read; i++) {
        bool ok = true;
        for (size_t j = 0; j < plen; j++) {
            if (mask[j] == 'x' && buf[i + j] != pat[j]) { ok = false; break; }
        }
        if (ok) { free(buf); return start + i; }
    }
    free(buf);
    return 0;
}
```

