先看当前可用的执行槽位与工具状态：

```
reverse_preflight
reverse_agent_slot(action=status)
```

同时给出这一轮 `dynamic` 子任务要跑的取偏移代码骨架（占位符按实际进程名/模块名替换，参数缺就往下走）：

```c
// hp_offset_probe.c — x64, MSVC / cl
// 用法: hp_probe.exe [进程名] [模块名] [当前血量]
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>
#include <stdlib.h>

static DWORD find_pid(const char* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe = { .dwSize = sizeof(pe) };
    DWORD pid = 0;
    if (Process32First(snap, &pe)) do {
        if (!_stricmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    } while (Process32Next(snap, &pe));
    CloseHandle(snap);
    return pid;
}

static ULONGLONG mod_base(DWORD pid, const char* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32 me = { .dwSize = sizeof(me) };
    ULONGLONG base = 0;
    if (Module32First(snap, &me)) do {
        if (!_stricmp(me.szModule, mod)) { base = (ULONGLONG)me.modBaseAddr; break; }
    } while (Module32Next(snap, &me));
    CloseHandle(snap);
    return base;
}

int main(int argc, char** argv) {
    const char* proc = argc > 1 ? argv[1] : "[进程名].exe";
    const char* mod  = argc > 2 ? argv[2] : "[模块名].exe";
    int hp           = argc > 3 ? atoi(argv[3]) : -1;

    DWORD pid = find_pid(proc);
    if (!pid) { printf("pid not found\n"); return 1; }
    printf("pid=%lu base=%llx\n", pid, mod_base(pid, mod));

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("OpenProcess=%lu\n", GetLastError()); return 1; }

    // 第一轮：按 4 字节 int 扫描已提交可读写区，筛 hp 值
    SYSTEM_INFO si; GetSystemInfo(&si);
    ULONGLONG addr = (ULONGLONG)si.lpMinimumApplicationAddress;
    ULONGLONG max  = (ULONGLONG)si.lpMaximumApplicationAddress;
    unsigned char buf[0x10000];
    int hits = 0;
    while (addr < max) {
        MEMORY_BASIC_INFORMATION mbi;
        if (!VirtualQueryEx(h, (LPCVOID)addr, &mbi, sizeof(mbi))) break;
        if (mbi.State == MEM_COMMIT &&
            (mbi.Protect == PAGE_READWRITE || mbi.Protect == PAGE_EXECUTE_READWRITE)) {
            SIZE_T done = 0;
            while (done < mbi.RegionSize) {
                SIZE_T chunk = min(sizeof(buf), mbi.RegionSize - done);
                SIZE_T got = 0;
                if (ReadProcessMemory(h, (LPCVOID)((ULONGLONG)mbi.BaseAddress + done), buf, chunk, &got) && got) {
                    for (SIZE_T i = 0; i + 4 <= got; i += 4) {
                        int v = *(int*)(buf + i);
                        if (hp >= 0 && v == hp) {
                            printf("hit %llx = %d\n", (ULONGLONG)mbi.BaseAddress + done + i, v);
                            if (++hits > 200) goto out;
                        }
                    }
                }
                done += chunk;
            }
        }
        addr = (ULONGLONG)mbi.BaseAddress + mbi.RegionSize;
    }
out:
    printf("total hits=%d\n", hits);
    CloseHandle(h);
    return 0;
}
```

编译与首轮执行：

```bat
cl /O2 /nologo hp_offset_probe.c
hp_offset_probe.exe [进程名].exe [模块名].exe [当前血量]
```

